import pandas as pd

def run(inputs: dict) -> dict:
    events = inputs["events"].copy()

    if events.empty:
        return {
            "channel_sessions": pd.DataFrame(
                columns=[
                    "user_id", "channel", "session_num",
                    "session_start", "session_end", "event_count"
                ]
            )
        }

    events = events.sort_values(
        by=["user_id", "channel", "event_ts", "event_id"],
        kind="mergesort"
    ).reset_index(drop=True)

    grp_keys = ["user_id", "channel"]

    prev_ts = events.groupby(grp_keys)["event_ts"].shift(1)
    gap = events["event_ts"] - prev_ts
    new_session = prev_ts.isna() | (gap > pd.Timedelta(minutes=25))

    session_id = new_session.groupby([events["user_id"], events["channel"]]).cumsum()

    events["_session_id"] = session_id

    grouped = events.groupby(grp_keys + ["_session_id"], sort=False).agg(
        session_start=("event_ts", "min"),
        session_end=("event_ts", "max"),
        event_count=("event_id", "count")
    ).reset_index()

    grouped = grouped.sort_values(
        by=["user_id", "channel", "session_start"],
        kind="mergesort"
    ).reset_index(drop=True)

    grouped["session_num"] = grouped.groupby(grp_keys).cumcount() + 1

    result = grouped[
        ["user_id", "channel", "session_num", "session_start", "session_end", "event_count"]
    ].reset_index(drop=True)

    return {"channel_sessions": result}
